use gotivi::{convert,Mode};fn main(){let mut a=std::env::args().skip(1);let mut m=Mode::Telex;let mut t=None;let mut demo=false;while let Some(v)=a.next(){match v.as_str(){"--mode"=>m=Mode::from(&a.next().unwrap_or_default()),"--text"=>t=a.next(),"--demo"=>demo=true,_=>{eprintln!("Usage: gotivi --demo | --text TEXT [--mode telex|simple|vni|viqr|english]");return}}}if demo{for s in ["Tieengs Vieejt","thuowng","dd","ko vn"]{println!("{} → {}",s,convert(s,m))}}else if let Some(s)=t{println!("{}",convert(&s,m))}else{use std::io::{self,BufRead};for s in io::stdin().lock().lines().flatten(){println!("{}",convert(&s,m))}}}